import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.SkWZtmk2.js";const g=JSON.parse('{"title":"核心概念","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),n={name:"guide/concepts.md"};function c(r,e,s,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h1><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><p>库按「框架无关内核 + 能力层」分层，依赖只自上而下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>core（框架无关：文档模型 · 几何 · 数据上下文 · 事件 · 注册表）</span></span>
<span class="line"><span>  ▲</span></span>
<span class="line"><span>  ├─ elements  九种内置元素定义</span></span>
<span class="line"><span>  ├─ designer  可视化设计器（状态 · 命令 · 插件 · 视图）</span></span>
<span class="line"><span>  ├─ parser    文档展开与 HTML / PDF 解析器、渲染运行时</span></span>
<span class="line"><span>  └─ 外部插件  独立 package（如 SaaS 服务集成）</span></span></code></pre></div><ul><li><code>core</code> 不依赖任何上层模块。</li><li><code>parser</code> 同样不依赖设计器，可脱离设计器独立使用——<code>createPrinter()</code> 即基于此。</li></ul><h2 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>职责</th><th>包入口</th></tr></thead><tbody><tr><td>core</td><td>文档模型、页面与元素结构、数据上下文与绑定表达式、元素注册表、错误类型</td><td><code>@printstack/print-studio/core</code></td></tr><tr><td>elements</td><td>内置元素定义：属性 Schema、渲染、测量与分页能力</td><td>Designer 默认全量；Printer 默认全量，也支持显式集合</td></tr><tr><td>designer</td><td>设计器界面、状态管理、命令与事件、插件系统、挂载入口</td><td><code>/designer</code>、<code>/vue</code></td></tr><tr><td>parser</td><td>渲染前文档展开、HTML / PDF 解析器、渲染运行时</td><td>随主入口、<code>/runtime</code></td></tr><tr><td>外部插件</td><td>可选业务插件与外部服务集成</td><td><code>@printstack/saas</code></td></tr></tbody></table><h2 id="模块之间的关系" tabindex="-1">模块之间的关系 <a class="header-anchor" href="#模块之间的关系" aria-label="Permalink to &quot;模块之间的关系&quot;">​</a></h2><ul><li><strong>注册表协作</strong>：<code>designer</code> 与 <code>parser</code> 经 <code>elementRegistry</code> / <code>parserRegistry</code> 查找元素与解析器能力，不出现按元素类型硬编码的分支；两侧注册的定义需保持一致。</li><li><strong>编辑与输出分离</strong>：<code>designer</code> 只负责编辑与状态，输出一律走 <code>parser</code> 模块的渲染管线。</li><li><strong>插件经契约访问宿主</strong>：业务插件通过 <code>PluginDefinition</code> 契约获得按权限约束的能力（命令、事件、面板、文档读写），不直连内部状态，见<a href="./../reference/plugins.html">插件与扩展</a>。</li></ul><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ul><li><strong>模板与数据分离</strong>：模板 JSON 持久化，业务数据渲染时注入，不写回模板。</li><li><strong>文档是唯一数据源</strong>：文档数据只存于文档模型，编辑统一提交历史（撤销 / 重做），不另存副本。</li><li><strong>注册表驱动</strong>：元素、解析器、命令、面板等能力按标识注册查找，新增能力不改内核代码（开闭原则）。</li><li><strong>命令与事件是统一入口</strong>：菜单、快捷键等动作都是命令；状态变化派生语义事件（如 <code>selection:changed</code>），扩展方监听而非侵入。</li><li><strong>异常分类处理</strong>：编程错误直接抛出快速失败；领域操作失败抛出 <code>DesignerException</code> 统一展示；预期分支（未选中、用户取消）不作为异常。</li></ul><h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to &quot;核心术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文 / 代码</th><th>说明</th></tr></thead><tbody><tr><td>文档</td><td>Document / <code>PrintDocument</code></td><td>可保存为 JSON 的完整模板模型</td></tr><tr><td>页面</td><td>Page / <code>PageNode</code></td><td>单个打印页面，有物理尺寸与元素列表</td></tr><tr><td>画布</td><td>Canvas</td><td>承载页面的编辑视图，可平移缩放，不是纸张本身</td></tr><tr><td>元素</td><td>Element / <code>ElementNode</code></td><td>页面中的可编辑对象（文本、表格、条形码等）</td></tr><tr><td>元素定义</td><td>Element Definition / <code>ElementDefinition</code></td><td>一种元素类型的属性与能力描述，不是元素实例</td></tr><tr><td>图层</td><td>Layer</td><td>图层面板中元素的呈现与叠放，一个元素即一个图层</td></tr><tr><td>页面模板</td><td>Page Template / <code>PageTemplate</code></td><td>多页共用的页眉页脚等内容，InDesign 主页式母版</td></tr><tr><td>数据源</td><td>Data Source / <code>DataSource</code></td><td>模板级数据结构声明，<code>key</code> 对应打印输入顶层键</td></tr><tr><td>数据绑定</td><td>Data Binding / <code>bindings</code></td><td>元素属性关联数据字段的机制</td></tr><tr><td>打印数据</td><td>Print Input / <code>input</code></td><td>渲染时注入的实际业务数据</td></tr><tr><td>循环区块</td><td>Repeat Group / <code>RepeatGroup</code></td><td>一组元素按数组数据重复排布</td></tr><tr><td>跟随块</td><td>Follow Block / <code>FollowBlock</code></td><td>元素组跟随目标（表格 / 循环区块）排布的区块</td></tr><tr><td>文档展开</td><td>Document Expansion / <code>expandDocument</code></td><td>渲染前解析绑定、物化循环区块并自动分页</td></tr><tr><td>解析器</td><td>Parser / <code>DocumentParser</code></td><td>把展开后的文档转为 HTML、PDF 等输出</td></tr><tr><td>命令</td><td>Command / <code>CommandRegistry</code></td><td>菜单与快捷键动作的统一执行入口</td></tr><tr><td>事件</td><td>Event / <code>DesignerEventMap</code></td><td>状态与动作的语义通知，如 <code>selection:changed</code></td></tr></tbody></table><h2 id="文档-printdocument-与「模板」" tabindex="-1">文档（PrintDocument）与「模板」 <a class="header-anchor" href="#文档-printdocument-与「模板」" aria-label="Permalink to &quot;文档（PrintDocument）与「模板」&quot;">​</a></h2><p>一份文档 = 一个可保存为 JSON 的打印模板，包含页面、元素、数据源、页面模板与循环配置。<code>studio.document</code> 管理它；<code>studio.export.json()</code> 序列化。业务上说的「维护模板」就是维护这份 JSON。</p><h2 id="页面-pagenode" tabindex="-1">页面（PageNode） <a class="header-anchor" href="#页面-pagenode" aria-label="Permalink to &quot;页面（PageNode）&quot;">​</a></h2><p>文档由页面数组组成。每页有 <code>width/height</code>（mm）、<code>margins</code>、<code>background</code>、<code>elements</code> 与可选 <code>templateId</code>。<strong>方向由宽高关系表达</strong>：<code>width &gt; height</code> 即横版。元素数组索引 0 在最底层。</p><h2 id="元素-elementnode" tabindex="-1">元素（ElementNode） <a class="header-anchor" href="#元素-elementnode" aria-label="Permalink to &quot;元素（ElementNode）&quot;">​</a></h2><p>页面内容的原子单元：<code>text / rect / ellipse / line / image / barcode / qrcode / table / pen-path</code> 九种内置类型。通用字段（位置、尺寸、旋转、不透明度、锁定、显隐）+ 类型专属 <code>props</code>。所有元素经注册表驱动，新增类型即注册 <code>ElementDefinition</code>。</p><p><strong>线条是点驱动元素</strong>：几何由 <code>points</code>（页面坐标中的两端点）定义，包围盒为派生值，<code>rotation</code> 恒为 0。钢笔路径的锚点和控制柄则保存在路径局部坐标中，元素仍通过定界框定位、缩放和旋转。</p><h2 id="页面模板-pagetemplate-——不是「模板库」" tabindex="-1">页面模板（PageTemplate）——不是「模板库」 <a class="header-anchor" href="#页面模板-pagetemplate-——不是「模板库」" aria-label="Permalink to &quot;页面模板（PageTemplate）——不是「模板库」&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>API</th></tr></thead><tbody><tr><td>页面模板</td><td>多个页面共用的页眉、页脚、背景等内容</td><td><code>studio.template</code></td></tr><tr><td>模板库</td><td>整份文档的可复用副本</td><td>业务层自行存储 JSON</td></tr></tbody></table><p>页面模板支持继承（<code>baseTemplateId</code>）、双面（<code>facingPages</code> + 偶数页变体）、表尾溢出延续（长表格的溢出行延续到页面模板承载的专属页面）。渲染时模板元素显示在页面元素下方。</p><h2 id="数据源与绑定" tabindex="-1">数据源与绑定 <a class="header-anchor" href="#数据源与绑定" aria-label="Permalink to &quot;数据源与绑定&quot;">​</a></h2><p>数据源（<code>dataSource</code>）声明数据结构与示例数据；绑定把元素属性连到数据字段：</p><ul><li><strong>表达式绑定</strong>：字符串属性内嵌 <span><code>{{ 路径 | 格式化:参数 }}</code></span>。</li><li><strong>结构化绑定</strong>：<code>bindings: { rows: &#39;items&#39; }</code>（表格数组行）；循环成员内直接用行字段与 <code>$index</code>。</li><li><strong>文档变量</strong>：<code>$document.pageNumber/pageCount/now/documentName/pageName</code>。</li></ul><p>渲染时注入的 <code>input</code> 按 <code>key</code> 对应数据源，<strong>不写回模板</strong>。</p><h2 id="循环区块与跟随块" tabindex="-1">循环区块与跟随块 <a class="header-anchor" href="#循环区块与跟随块" aria-label="Permalink to &quot;循环区块与跟随块&quot;">​</a></h2><ul><li><strong>循环区块（RepeatGroup）</strong>：一组元素按数组数据平铺，<code>direction</code> 支持 <code>grid</code> 网格（标签平铺）、<code>page</code> 每条数据一页、<code>vertical</code> 纵向列表，超页自动分页；<code>positionMode: &#39;flow&#39;</code> 时后续内容上移。</li><li><strong>跟随块（FollowBlock）</strong>：元素始终跟随目标（表格 / 循环区块）末尾，间距 <code>gap</code>，签字区场景。</li></ul><p>循环区块和跟随块的画布角标随画布同比例缩放。</p><h2 id="表格跨页与合计" tabindex="-1">表格跨页与合计 <a class="header-anchor" href="#表格跨页与合计" aria-label="Permalink to &quot;表格跨页与合计&quot;">​</a></h2><ul><li><strong>跨页续排</strong>：<code>pagination.crossPage</code> 开启后长表格自动分页，延续页可重复表头（<code>repeatHeader</code>）。</li><li><strong>补空行</strong>：<code>fillEmptyRows</code> 用空白行补满本页余量；配置 <code>rowsPerPage</code> 时补齐到固定行数。</li><li><strong>合计</strong>：<code>summary</code> 提供每页小计（<code>scope: &#39;eachPage&#39;</code>）与全量合计（<code>scope: &#39;lastPage&#39;</code>）。</li></ul><h2 id="数据流与执行机制" tabindex="-1">数据流与执行机制 <a class="header-anchor" href="#数据流与执行机制" aria-label="Permalink to &quot;数据流与执行机制&quot;">​</a></h2><p>编辑态：设计器内的工具与命令修改文档模型并统一提交历史；状态变化派生语义事件，扩展方通过事件与状态快照感知，不直接改写内部数据。</p><p>输出态：所有输出走同一条管线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input → 解析绑定 → 文档展开（循环区块物化、自动分页）→ 输出解析器渲染 → HTML / PDF</span></span></code></pre></div><p>展开后的中间结果仍是合法 <code>PrintDocument</code>——HTML / PDF 解析器对绑定无感知。执行后端可选主线程 / Worker / 混合（<code>rendering.worker</code>），<code>execution</code> 字段用于诊断。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>createDesigner()  ──mount()──▶ 设计器视图（按需加载）</span></span>
<span class="line"><span>      │                     │</span></span>
<span class="line"><span>      │◀──── unmount() ─────┘   只卸视图，实例保留</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>   dispose()  销毁实例（联动 unmount），实例不可再用</span></span></code></pre></div><ul><li><code>mount</code> resolve 即界面与插件就绪；一个实例同时只挂载一个设计器。</li><li><code>useDesigner()</code> 本次创建的实例随 Vue 作用域销毁自动 <code>dispose</code>。</li><li>纯输出实例 <code>createPrinter()</code> 用完 <code>dispose()</code>。</li></ul><h2 id="快照语义" tabindex="-1">快照语义 <a class="header-anchor" href="#快照语义" aria-label="Permalink to &quot;快照语义&quot;">​</a></h2><p>所有查询返回快照或句柄：</p><ul><li>句柄：<code>{ id, data, update, remove }</code>；删除后 <code>data</code> 为 <code>undefined</code>。</li><li>集合：<code>list</code> 是属性不是函数；<code>get(ref)</code> 接收 ID 或 <code>{ id }</code> 对象。</li><li>修改必须走句柄 / 集合方法；直接改快照不生效。</li></ul><h2 id="右侧属性检查器" tabindex="-1">右侧属性检查器 <a class="header-anchor" href="#右侧属性检查器" aria-label="Permalink to &quot;右侧属性检查器&quot;">​</a></h2><ul><li><strong>文档</strong>：未选择元素时显示文档名称、页数和当前页尺寸。操作提示可关闭；选择元素后，此区块切换为元素属性。</li><li><strong>页面</strong>：使用「页面」「模板」标签切换列表，在标题右侧新增。在行上右键，或悬停后点击「更多操作」，可管理页面或模板。</li><li><strong>图层</strong>：按名称或元素类型搜索，并按显隐或锁定状态筛选。搜索或筛选会显示折叠组中的匹配项，不改变组原本的折叠状态；清除筛选后可继续拖拽排序。选中一个未锁定元素时，可通过滑块或百分比输入修改不透明度。</li></ul><p>点击区块标题可折叠或展开。拖动展开区块底部的分隔线调整高度（最小 120 px），双击分隔线恢复自动高度。高度和折叠状态随面板布局保留。默认布局下，文档和页面区块按内容占用空间，图层列表使用剩余高度。右栏外观随设计器主题切换。</p><p>拖拽面板时，落点提示显示在拖拽预览下方，不遮挡正在移动的内容。</p>`,47)])])}const u=t(n,[["render",c]]);export{g as __pageData,u as default};
